Exemplo:

    package main

    import "fmt"

    type demo struct {
     Val int
    }

    func (d *demo) change() {
     d = nil // Atribuição ao receptor do método propaga-se apenas aos métodos chamados, mas não aos métodos chamadores
     d.myVal()
    }

    func (d *demo) myVal() {
     fmt.Printf("my val: %#v\n", d)
    }

    func (d demo) change2() {
     d = demo{} // Atribuição ao receptor do método não se propaga para outras chamadas
     d.myVal()
    }

    func (d *demo) change3() {
     d.Val = 3
     d.myVal()
    }

    func main() {
     d := &demo{}
     d.myVal()
     d.change()
     d.myVal()
     d.Val = 2
     d.change2()
     d.myVal()
     d.change3()
     d.myVal()
